    const eta = ((47.0029 - 0.06603 * T + 0.000598 * T * T) * t + (-0.03302 + 0.000598 * T) * t * t + 0.00006 * t ** 3) / 3600;
    const Pi = 174.876384 + (3289.4789 * T + 0.60622 * T * T - (869.8089 + 0.50491 * T) * t + 0.03536 * t * t) / 3600;
    const p = ((5029.0966 + 2.22226 * T - 0.000042 * T * T) * t + (1.11113 - 0.000042 * T) * t * t - 0.000006 * t ** 3) / 3600;
    const a = cosd(eta) * cosd(lat) * sind(Pi - lon) - sind(eta) * sind(lat);
    const b = cosd(lat) * cosd(Pi - lon);
