  const VSOP = {};
  (function unpack() {
    if (!VSOP_RAW) return;
    for (const k in VSOP_RAW) VSOP[k] = VSOP_RAW[k].map(ser => ser.map(arr => { const f = new Float64Array(arr.length); for (let i = 0; i < arr.length; i += 3) { f[i] = arr[i] / 1e10; f[i + 1] = arr[i + 1]; f[i + 2] = arr[i + 2]; } return f; }));
  })();
  function vsopSeries(ser, tau, maxTerms) {
    let s = 0, tp = 1;
    for (let a = 0; a < ser.length; a++) {
      const f = ser[a]; let x = 0;
      const n = maxTerms ? Math.min(f.length, maxTerms * 3) : f.length;
      for (let i = 0; i < n; i += 3) x += f[i] * Math.cos(f[i + 1] + f[i + 2] * tau);
      s += x * tp; tp *= tau;
    }
    return s;
  }
  // heliocentric ecliptic rectangular coords (AU), mean ecliptic & equinox of date (VSOP dynamical frame)
  function helioRect(body, jdTT, maxTerms) {
    const tau = (jdTT - J2000) / 365250, S = VSOP[body];
    const L = vsopSeries(S[0], tau, maxTerms), B = vsopSeries(S[1], tau, maxTerms), R = vsopSeries(S[2], tau, maxTerms);
    const cb = Math.cos(B);
    return [R * cb * Math.cos(L), R * cb * Math.sin(L), R * Math.sin(B)];
  }

