      const ox = occupied[x], oy = occupied[y];
      if (r[x] === 0 || r[y] === 0) continue;
      if (ox && oy) continue;
      if (!ox && !oy) { if (r[x] === r[y]) { r[x] = 0; r[y] = 0; } else { const m = Math.min(r[x], r[y]); r[x] = m; r[y] = m; } continue; }
