    const kendraVal = h => [1, 4, 7, 10].includes(h) ? 60 : [2, 5, 8, 11].includes(h) ? 30 : 15;
    const vSigns = D => { const s = {}; for (const id of PL9) s[id] = vargaSign(P[id].lon, D); return s; };
    const SV = { 1: signs, 2: vSigns(2), 3: vSigns(3), 7: vSigns(7), 9: vSigns(9), 12: vSigns(12), 30: vSigns(30) };
