      const dk = Math.floor(d / 10), drek = (['Su', 'Ma', 'Ju'].includes(id) && dk === 0) || (['Me', 'Sa'].includes(id) && dk === 1) || (['Mo', 'Ve'].includes(id) && dk === 2) ? 15 : 0;
      const sthana = { uchcha, saptavargaja: sapta, ojayugma: oj, kendradi, drekkana: drek };
      // --- Dig (strong points: Su/Ma MC, Ju/Me Asc, Mo/Ve IC, Sa Desc)
