    const mercBen = !['Su', 'Ma', 'Sa', 'Ra', 'Ke'].some(m => signs[m] === signs.Me);
    const isBen = id => id === 'Ju' || id === 'Ve' || (id === 'Me' && mercBen) || (id === 'Mo' && waxing);
    const isMal = id => MALEFIC_NAT.includes(id) || (id === 'Me' && !mercBen) || (id === 'Mo' && !waxing);
    const BEN3 = ['Me', 'Ju', 'Ve'];
    const dig = id => P[id].dignity;
    const ownEx = id => ['exalted', 'moolatrikona', 'own'].includes(dig(id));
    const ownExSign = id => (OWN[id] || []).includes(S(id)) || (EXALT[id] && EXALT[id][0] === S(id));
    const debil = id => dig(id) === 'debilitated';
    const exalted = id => EXALT[id] && EXALT[id][0] === S(id);
    const deepEx = id => exalted(id) && Math.abs(nrm180(P[id].lon - (EXALT[id][0] * 30 + EXALT[id][1]))) <= 5;
    const sb = C.shadbala;
    const strong = id => ownEx(id) || (sb[id] && sb[id].ratio >= 1 && !P[id].combust && !debil(id)) || (!sb[id] && ownEx(id));
    const conj = (a, b) => a !== b && signs[a] === signs[b];
