    const connect = (a, b) => a === b ? null : conj(a, b) ? 'conj' : exch(a, b) ? 'exch' : mutual(a, b) ? 'mutual' : null;
    const connT = c => ({ same: T('the same planet', 'एक ही ग्रह'), conj: T('conjunction', 'युति'), exch: T('sign exchange', 'राशि परिवर्तन'), mutual: T('mutual aspect', 'परस्पर दृष्टि') })[c];
    const navLord = id => lordS(C.vargas.D9.planets[id]);
    const kendraOrTri = h => KEN.includes(h) || TRI.includes(h);
    const at = id => L(pnT(id), T(' in ' + SNAME[S(id)].en + ' (' + HOUSE_ORD(H(id)).en + ' house)', ' ' + SNAME[S(id)].hi + ' में (' + HOUSE_ORD(H(id)).hi + ' भाव)'));
    const ats = ids => LJ(ids.map(at), '; ', '; ');
    const scoreOf = id => (ownEx(id) ? 2 : ['friend', 'great_friend'].includes(dig(id)) ? 1 : debil(id) ? -2 : ['enemy', 'great_enemy'].includes(dig(id)) ? -1 : 0) - (P[id].combust ? 1 : 0) + (sb[id] && sb[id].ratio >= 1 ? 1 : 0);
    const strengthOf = ids => { const v = ids.filter(x => PL7.includes(x)); if (!v.length) return 'medium'; const a = v.reduce((s, x) => s + scoreOf(x), 0) / v.length; return a >= 1.5 ? 'strong' : a >= 0.3 ? 'medium' : 'weak'; };
