      const h = rel('Mo', 'Ju'), weak = debil('Ju') || P.Ju.combust || ['enemy', 'great_enemy'].includes(dig('Ju')), ok = KEN.includes(h) && !(strict && weak);
      add('gajakesari', ok, { planets: ['Ju', 'Mo'], houses: [H('Ju'), H('Mo')], strength: weak ? 'weak' : strengthOf(['Ju', 'Mo']),
        reason: ok ? L(T('Jupiter is in the ' + HOUSE_ORD(h).en + ' house from the Moon (a kendra)', 'गुरु चंद्रमा से ' + HOUSE_ORD(h).hi + ' भाव (केंद्र) में है'), weak ? T('; Jupiter is weak (debilitated, combust or in an enemy sign), so the yoga is mild.', '; गुरु कमज़ोर (नीच, अस्त या शत्रु राशि) है, इसलिए योग हल्का है।') : T('.', '।'))
          : NOT('Jupiter is ' + HOUSE_ORD(h).en + ' from the Moon, not in a kendra.', 'गुरु चंद्रमा से ' + HOUSE_ORD(h).hi + ' भाव में है, केंद्र में नहीं।') });
