        while (u < t2) { const u2 = Math.min(t2, u + 4); const r = signIngresses(fn, u, u2, 4, null); for (const e of r) { if (e.from === s) { out.push(e); s = e.to; } } u = u2; }
        t = t2; fPrev = f2; continue;
