    const jd0 = julianDay(fromYear || calFromJd(C.meta.jdUT).y, 1, 1), jd1 = julianDay((toYear || (fromYear || calFromJd(C.meta.jdUT).y) + 100) + 1, 1, 1);
    const fn = j => saturnSid(j, ay);
    const ing = signIngresses(fn, jd0, jd1, 16, j => saturnSidFast(j, ay));
    const phaseOf = s => { const h = ((s - mo + 12) % 12) + 1; return h === 12 ? 'rising' : h === 1 ? 'peak' : h === 2 ? 'setting' : h === 4 ? 'dhaiya4' : h === 8 ? 'dhaiya8' : null; };
    const periods = [];
    let curS = signOf(fn(jd0)), curStart = jd0;
    const push = (s, a, b, openStart, openEnd) => { const ph = phaseOf(s); if (ph) periods.push({ phase: ph, sign: s, start: a, end: b, startISO: isoLocal(a, off), endISO: isoLocal(b, off), openStart: !!openStart, openEnd: !!openEnd }); };
    for (const e of ing) { push(curS, curStart, e.jd, curStart === jd0, false); curS = e.to; curStart = e.jd; }
    push(curS, curStart, jd1, curStart === jd0, true);
