    if (typeof date === 'string') { const [d, t] = date.split('T'); const [y, m, dd] = ymd(d); const tp = (t || '12:00').split(':').map(Number); return julianDay(y, m, dd, tp[0] + (tp[1] || 0) / 60 + (tp[2] || 0) / 3600 - (off || 0)); }
